import { dirname } from "path";
import { fileURLToPath } from "url";
import { FlatCompat } from "@eslint/eslintrc";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const compat = new FlatCompat({ baseDirectory: __dirname });

export default [
  ...compat.extends("next/core-web-vitals", "next/typescript"),
  {
    // `next-env.d.ts` is generated by `next build`/`next dev`, is gitignored, and says in
    // its own body that it must not be edited. Next 15 emits a triple-slash *path*
    // reference in it, which `@typescript-eslint/triple-slash-reference` rejects — so
    // without this, `pnpm check` goes red for anyone who has ever run the app, on a file
    // nobody may fix. CI never saw it because it lints before it builds.
    ignores: [".next/**", "node_modules/**", "src/generated/**", "next-env.d.ts"],
  },
  {
    rules: {
      // Configuration has exactly one home. `process.env` read anywhere else is a second
      // place a variable name can be misspelled, a second thing to keep in step with the
      // template, and a value that skipped validation. See src/platform/config/.
      //
      // The build mode is banned outright, in the config modules too: NODE_ENV has two
      // values and describes how the app was *compiled*, so one production build serves
      // staging and production alike. Reading it to answer an environment question is the
      // bug APP_ENV exists to remove (#96).
      "no-restricted-syntax": [
        "error",
        {
          selector: 'MemberExpression[object.name="process"][property.name="env"]',
          message:
            "Read configuration through @/platform/config/server or @/platform/config/public — they validate it and are the only modules that may touch process.env.",
        },
        {
          selector: 'MemberExpression[property.name="NODE_ENV"]',
          message:
            "NODE_ENV is the build mode, not the environment. Read `environment` from @/platform/config/server — it is one of local, development, staging, production.",
        },
      ],
      // Architectural boundaries from CLAUDE.md, enforced by the linter.
      "no-restricted-imports": [
        "error",
        {
          patterns: [
            {
              // Generated wire types are raw transport. They may only be read
              // inside a feature's api/ or mappers/ layer.
              group: ["**/generated/*", "@/generated/*"],
              message:
                "Import generated wire types only inside a feature's api/ or mappers/ layer. Map them to your own DTO/domain objects first. See CLAUDE.md.",
            },
            {
              // The other apps are separate deployables; they communicate over
              // HTTP only. See docs/adr/0005.
              group: ["../../backend/**", "../../frontend_player/**"],
              message:
                "frontend_club must never import from another app. Apps talk over HTTP only. See docs/adr/0005.",
            },
          ],
        },
      ],
    },
  },
  {
    // The wire boundary: these two layers are exactly where generated types
    // are allowed to be read.
    files: ["src/features/*/api/**", "src/features/*/mappers/**"],
    rules: { "no-restricted-imports": "off" },
  },
  {
    // The config boundary: this is the one place `process.env` is legitimate, because it
    // is the place that validates it. NODE_ENV stays banned here — the exemption is for
    // reading configuration, not for asking the build mode where it is running.
    files: ["src/platform/config/**"],
    rules: {
      "no-restricted-syntax": [
        "error",
        {
          selector: 'MemberExpression[property.name="NODE_ENV"]',
          message:
            "NODE_ENV is the build mode, not the environment. Validate APP_ENV instead — it is one of local, development, staging, production.",
        },
      ],
    },
  },
  {
    // domain/ and use-cases/ are pure: no React, no Next, no fetch.
    files: ["src/features/*/domain/**", "src/features/*/use-cases/**"],
    rules: {
      "no-restricted-imports": [
        "error",
        {
          paths: [
            { name: "react", message: "domain/ and use-cases/ must stay pure TypeScript." },
            { name: "next", message: "domain/ and use-cases/ must stay pure TypeScript." },
          ],
          patterns: [
            {
              group: ["next/*", "react-dom", "**/generated/*", "@/generated/*"],
              message: "domain/ and use-cases/ must stay pure TypeScript — no React, Next, or wire types.",
            },
          ],
        },
      ],
    },
  },
];
